<?php defined('ABSPATH')||exit; ?>
<section class="rdl-prd-single rdc-ctr rdc-main"><?php while(have_posts()):the_post(); ?><article><h1><?php the_title(); ?></h1><?php if(post_password_required()){echo get_the_password_form();}else{$data=\RadmanLibrary\Catalog\Model\read(get_the_ID()); ?>
<a href="<?php echo esc_url(\RadmanLibrary\Catalog\url()); ?>">→ همهٔ محصولات</a><div class="rdl-prd-hero"><div><?php $cover=get_post_thumbnail_id();if(\RadmanLibrary\Catalog\image($cover)): ?><a href="<?php echo esc_url(wp_get_attachment_url($cover)); ?>" data-rdc-gal><?php echo wp_get_attachment_image($cover,'large',false,['loading'=>'eager','fetchpriority'=>'high','sizes'=>'(max-width:767px) 100vw,50vw']); ?></a><?php endif; ?>
<?php $gallery=array_values(array_filter(array_diff($data['gallery'],[$cover]),'RadmanLibrary\Catalog\image'));if($gallery): ?><div class="rdl-prd-gal"><?php foreach($gallery as $id): ?><a data-rdc-gal href="<?php echo esc_url(wp_get_attachment_url($id)); ?>"><?php echo wp_get_attachment_image($id,'medium',false,['loading'=>'lazy','sizes'=>'(max-width:600px) 30vw,15vw']); ?></a><?php endforeach; ?></div><?php endif; ?></div>
<div><?php if($data['code']): ?><p>کد محصول: <bdi><?php echo esc_html($data['code']); ?></bdi></p><?php endif; ?><?php if(has_excerpt())the_excerpt();foreach(\RadmanLibrary\Catalog\TAX as $tax=>$label)the_terms(get_the_ID(),$tax,'<p>'.esc_html($label).': ','، ','</p>'); ?>
<?php if($data['pricing']['mode']==='price'&&$data['pricing']['text']): ?><p class="rdl-prd-price"><?php echo esc_html($data['pricing']['text']); ?></p><?php endif; ?>
<?php $contact=apply_filters('rdl/catalog/contact_url','',get_the_ID());if(is_string($contact)&&$contact)echo \RadmanCT\button('درخواست اطلاعات محصول',$contact); ?>
<?php if($data['specifications']): ?><section><h2>مشخصات فنی</h2><dl class="rdl-prd-spec"><?php foreach($data['specifications'] as $row): ?><div><dt><?php echo esc_html($row['label']); ?></dt><dd><?php echo nl2br(esc_html($row['value']));if($row['unit'])echo ' '.esc_html($row['unit']); ?></dd></div><?php endforeach; ?></dl></section><?php endif; ?></div></div>
<div class="rdc-cnt"><?php the_content();wp_link_pages(); ?></div><nav class="rdl-prd-nav" aria-label="محصول قبلی و بعدی"><?php foreach([true,false] as $previous):$item=get_adjacent_post(false,'',$previous,'radman_product_cat');if(!$item||$item->post_status!=='publish'||$item->post_password)continue; ?><a href="<?php echo esc_url(get_permalink($item)); ?>"><?php echo $previous?'محصول قبلی: ':'محصول بعدی: ';echo esc_html($item->post_title); ?></a><?php endforeach; ?></nav>
<?php $terms=wp_get_object_terms(get_the_ID(),'radman_product_cat',['fields'=>'ids']);$args=['post_type'=>'radman_product','post_status'=>'publish','has_password'=>false,'posts_per_page'=>3,'post__not_in'=>[get_the_ID()],'no_found_rows'=>true];if($terms&&!is_wp_error($terms))$args['tax_query']=[['taxonomy'=>'radman_product_cat','field'=>'term_id','terms'=>$terms]];$related=get_posts($args);if($related): ?><section><h2>محصولات دیگر</h2><div class="rdl-prd-grid"><?php foreach($related as $item)\RadmanLibrary\Catalog\card($item,'h3'); ?></div></section><?php endif; ?>
<dialog class="rdc-lb rdc-inv" aria-label="نمایش تصویر محصول"><button type="button" data-rdc-lb-cls aria-label="بستن">بستن ×</button><img alt=""></dialog>
<?php } ?></article><?php endwhile; ?></section>
